function copyCanvasFromTo(e,t){const n=document.getElementById(e),a=document.getElementById(t).getContext("2d");a.drawImage(n,0,0)}function removeElementsByClass(e){const t=document.getElementsByClassName(e);for(;t.length>0;)t[0].parentNode.removeChild(t[0])}function downloadCanvas(e){const t=document.getElementById("canvas_final");var n=document.createElement("a");const a=new Date,o=(formatDate(a),"LM "+scale_multi+"k "+e+".png");n.download=o,console.log("Downloaded: ",o),n.href=t.toDataURL("image/png").replace("image/png","image/octet-stream"),n.click()}function formatDate(e){var t=e.getHours(),n=e.getMinutes(),a=t>=12?"pm":"am";t%=12,t=t||12,n=n<10?"0"+n:n;var o=t+"."+n+a;return e.getMonth()+1+"-"+e.getDate()+"-"+e.getFullYear()+" "+o}